const e="tpl-3d-full-body-gym",l=0,s="Full Body · 3 Days",t="flat-pyramid",r="2026-01-05",d=6,i="pt",n="Six weeks, three full-body sessions a week. Every muscle is trained each session with the same weight on every set. Day A is heavier, B is medium, C is lighter. Effort builds from week 1 to 5; week 6 is lighter.",o=[{title:"Goal",body:"Build muscle and strength on three days a week. Training each muscle three times spreads the weekly work into short, high-quality sessions, which suits busy schedules and people newer to lifting."},{title:"How it works",body:"Each session has a squat or hinge, a push, a pull and some arm and core work. Every set of an exercise uses the same weight and reps. Main lifts come first, alone, with 2-3 minutes rest. Paired exercises (same letter) are supersets: first exercise, about 10 seconds, second exercise, then the full rest."},{title:"A days vs B days",body:"This template has three different days instead of A/B copies. Day A is heavier (8-10 reps), day B is medium (10-12 reps) and day C is lighter (12-15 reps), each with different exercises, so you get variety and each rep range every week. Track each day separately."},{title:"How to progress",body:"Each exercise has a target rep number. When every set reaches it with clean form, add the smallest step next time (about 1-2.5 kg upper body, 2.5-5 kg legs). If you fall 1-2 reps short, keep the weight and beat it next week. Week 1 stop about 3 reps before failure, week 2 about 2, weeks 3-5 about 1-2."},{title:"What to expect",body:"Week 1 should feel easy while you find your weights. Weeks 2-5 should bring more reps or weight on most lifts. Leave at least one rest day between sessions when you can. Week 6 is lighter: same exercises and weights, half the sets (round up), about 3 reps before failure."},{title:"Key tips",body:"Warm up with 1-2 lighter sets of the first lift. If a machine is taken, swap to a similar exercise from the library and keep the reps. Never grind squats, deadlifts or presses to failure. If a movement hurts, stop it and see a qualified professional."}],a=[{key:"full-body-a",name:"Full Body A",focus:"Full body · heavy",exercises:[{code:"A1",exercise_id:"back-squat",sets:3,reps:["8","8","8"],rest_seconds:180,technique:"straight",angle_degrees:null,notes:""},{code:"B1",exercise_id:"barbell-bench-press",sets:3,reps:["8","8","8"],rest_seconds:150,technique:"straight",angle_degrees:0,notes:""},{code:"C1",exercise_id:"seated-cable-row",sets:3,reps:["10","10","10"],rest_seconds:10,technique:"superset",angle_degrees:null,notes:""},{code:"C2",exercise_id:"dumbbell-shoulder-press",sets:3,reps:["10","10","10"],rest_seconds:120,technique:"superset",angle_degrees:75,notes:""},{code:"D1",exercise_id:"romanian-deadlift",sets:3,reps:["10","10","10"],rest_seconds:150,technique:"straight",angle_degrees:null,notes:"Stop when your hips can't go further back."},{code:"E1",exercise_id:"ez-bar-curl",sets:2,reps:["12","12"],rest_seconds:10,technique:"superset",angle_degrees:null,notes:""},{code:"E2",exercise_id:"cable-rope-tricep-extensions",sets:2,reps:["12","12"],rest_seconds:60,technique:"superset",angle_degrees:null,notes:""},{code:"F1",exercise_id:"cable-crunch",sets:2,reps:["12","12"],rest_seconds:60,technique:"straight",angle_degrees:null,notes:""}]},{key:"full-body-b",name:"Full Body B",focus:"Full body · medium",exercises:[{code:"A1",exercise_id:"hex-bar-deadlift",sets:3,reps:["8","8","8"],rest_seconds:180,technique:"straight",angle_degrees:null,notes:""},{code:"B1",exercise_id:"lat-pulldown",sets:3,reps:["10","10","10"],rest_seconds:120,technique:"straight",angle_degrees:null,notes:""},{code:"C1",exercise_id:"incline-dumbbell-press",sets:3,reps:["10","10","10"],rest_seconds:10,technique:"superset",angle_degrees:30,notes:""},{code:"C2",exercise_id:"cable-lateral-raise",sets:3,reps:["15","15","15"],rest_seconds:90,technique:"superset",angle_degrees:null,notes:""},{code:"D1",exercise_id:"dumbbell-bulgarian-split-squat",sets:2,reps:["10","10"],rest_seconds:90,technique:"straight",angle_degrees:null,notes:"Reps are per leg."},{code:"E1",exercise_id:"seated-leg-curl-toes-dorsiflexed-neutral",sets:3,reps:["12","12","12"],rest_seconds:10,technique:"superset",angle_degrees:null,notes:""},{code:"E2",exercise_id:"standing-calf-raises-toes-neutral",sets:3,reps:["15","15","15"],rest_seconds:60,technique:"superset",angle_degrees:null,notes:""},{code:"F1",exercise_id:"dead-bug",sets:2,reps:["10","10"],rest_seconds:45,technique:"straight",angle_degrees:null,notes:""}]},{key:"full-body-c",name:"Full Body C",focus:"Full body · light",exercises:[{code:"A1",exercise_id:"leg-press-quad-dominant",sets:3,reps:["12","12","12"],rest_seconds:120,technique:"straight",angle_degrees:null,notes:""},{code:"B1",exercise_id:"machine-chest-press-incline",sets:3,reps:["12","12","12"],rest_seconds:10,technique:"superset",angle_degrees:null,notes:""},{code:"B2",exercise_id:"dumbbell-chest-supported-row",sets:3,reps:["12","12","12"],rest_seconds:120,technique:"superset",angle_degrees:30,notes:""},{code:"C1",exercise_id:"barbell-hip-thrust",sets:3,reps:["12","12","12"],rest_seconds:90,technique:"straight",angle_degrees:null,notes:""},{code:"D1",exercise_id:"cable-face-pull",sets:3,reps:["15","15","15"],rest_seconds:10,technique:"superset",angle_degrees:null,notes:""},{code:"D2",exercise_id:"lateral-raises-machine",sets:3,reps:["15","15","15"],rest_seconds:60,technique:"superset",angle_degrees:null,notes:""},{code:"E1",exercise_id:"dumbbell-curl-incline",sets:2,reps:["12","12"],rest_seconds:10,technique:"superset",angle_degrees:45,notes:""},{code:"E2",exercise_id:"rope-low-cable-oh-tricep-extensions",sets:2,reps:["12","12"],rest_seconds:60,technique:"superset",angle_degrees:null,notes:""},{code:"F1",exercise_id:"hanging-knee-raise",sets:2,reps:["12","12"],rest_seconds:60,technique:"straight",angle_degrees:null,notes:""}]}],c={id:e,number:0,name:s,method:t,start_date:r,weeks:6,origin:i,summary:n,insights:o,days:a};export{a as days,c as default,e as id,o as insights,t as method,s as name,l as number,i as origin,r as start_date,n as summary,d as weeks};
